bugRepair.brokenCode:
span.badge {
  width: 120px;
  height: 40px;
  /* النتيجة: المتصفح يتجاهل العرض والارتفاع تماماً */
}

.container {
  width: 800px;
  /* النتيجة: عند فتح الموقع على هاتف بعرض 400px يظهر شريط تمرير أفقي مكسور */
}

.card {
  /* الحاوية الأب */
}
.badge {
  position: absolute;
  top: 10px;
  right: 10px;
  /* المشكلة: الشارة تلتصق بأعلى زاوية صفحة المتصفح بدلاً من البطاقة! */
}

bugRepair.fixedCode:
.card {
  position: relative;
}
.badge {
  position: absolute;
  top: 10px;
  right: 10px;
}

bugRepair.brokenCode:
.card {
  position: static;
  top: 20px;
  left: 20px;
  /* النتيجة: العنصر لا يتحرك بكسلاً واحداً! */
}
